```java
// @Secured only checks roles — it cannot look at method parameters.
@Secured("ROLE_ADMIN") // must include the ROLE_ prefix explicitly
public Order getOrder(Long orderId, Long userId) {
    return orderRepository.findById(orderId).orElseThrow();
}
// No way to say "only the owner OR an admin" — @Secured has no access to userId.
```
Simple role-only checks are all @Secured can do.

```java
// @PreAuthorize uses SpEL: combine roles, read #params, add an admin override.
@PreAuthorize("#userId == authentication.principal.id or hasRole('ADMIN')")
public Order getOrder(Long orderId, Long userId) { // hasRole adds ROLE_ for you
    return orderRepository.findById(orderId).orElseThrow();
}
```
Ownership checks, logical operators, and bean calls are all possible with @PreAuthorize.

@Configuration
@EnableMethodSecurity  // Required to activate method security annotations
public class SecurityConfig {
}

@Service
public class OrderService {

    @PreAuthorize("hasRole('ADMIN')")
    public List<Order> getAllOrders() {
        return orderRepository.findAll();
    }

    // Only order owner or admin can view
    @PreAuthorize("#userId == authentication.principal.id or hasRole('ADMIN')")
    public Order getOrder(Long orderId, Long userId) {
        return orderRepository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(orderId));
    }

    @PreAuthorize("hasAuthority('ORDER_WRITE')")
    public Order createOrder(Order order) {
        order.setUserId(SecurityContextHolder.getContext().getAuthentication().getName());
        return orderRepository.save(order);
    }
}

@Service
public class UserService {

    // Simple role check
    @PreAuthorize("hasRole('ADMIN')")
    public List<User> getAllUsers() {
        return userRepository.findAll();
    }

    // Permission-based (more granular than roles)
    @PreAuthorize("hasAuthority('USER_DELETE')")
    public void deleteUser(Long userId) {
        userRepository.deleteById(userId);
    }

    // Owner-only access - parameter compared to logged-in user
    @PreAuthorize("#userId == authentication.principal.id or hasRole('ADMIN')")
    public User updateProfile(Long userId, UserUpdateRequest request) {
        var user = userRepository.findById(userId).orElseThrow();
        user.setEmail(request.email());
        return userRepository.save(user);
    }

    // Combining multiple conditions
    @PreAuthorize("isAuthenticated() and (#order.userId == authentication.principal.id or hasRole('SUPPORT'))")
    public void cancelOrder(Order order) {
        order.setStatus(OrderStatus.CANCELLED);
        orderRepository.save(order);
    }
}

