// URL security only sees the path — any logged-in user can hit any order ID.
@Bean
SecurityFilterChain chain(HttpSecurity http) throws Exception {
    return http
        .authorizeHttpRequests(auth -> auth
            .requestMatchers("/api/orders/**").authenticated()) // path only
        .build();
}
// GET /api/orders/999 succeeds even if order 999 belongs to someone else.
```
The filter cannot tell whose data the ID refers to.

```java
// Method security inspects the loaded data and enforces ownership.
@Service
public class OrderService {
    @PostAuthorize("returnObject.userId == authentication.principal.id")
    public Order getOrder(Long orderId) { // works on any call path, not just HTTP
        return orderRepository.findById(orderId).orElseThrow();
    }
}
```
Now a user can only read their own order, even if they change the ID in the URL.

@Service
public class DocumentService {
    @Autowired
    private DocumentRepository documentRepository;

    @PostAuthorize("returnObject.ownerId == authentication.principal.userId")
    public Document getDocument(Long documentId) {
        return documentRepository.findById(documentId)
            .orElseThrow(() -> new DocumentNotFoundException(documentId));
    }

    // More complex example with nested properties
    @PostAuthorize("returnObject.department.teamLead == authentication.name")
    public ProjectReport getReport(Long reportId) {
        var report = documentRepository.findReportById(reportId);
        // returnObject refers to this returned report
        return report;
    }

    // Works with collections too
    @PostAuthorize("returnObject.stream().allMatch(doc -> doc.ownerId == authentication.principal.userId)")
    public List<Document> getDocumentBatch(List<Long> ids) {
        return documentRepository.findAllById(ids);
    }
}

@SpringBootTest
@AutoConfigureMockMvc
class OrderControllerSecurityTest {
    @Autowired
    private MockMvc mockMvc;

    @Test
    @WithMockUser(roles = "ADMIN")
    void adminCanDeleteOrder() throws Exception {
        mockMvc.perform(delete("/api/orders/123"))
            .andExpect(status().isNoContent());
    }

    @Test
    @WithMockUser(roles = "USER")  // Wrong role
    void userCannotDeleteOrder() throws Exception {
        mockMvc.perform(delete("/api/orders/123"))
            .andExpect(status().isForbidden());  // Expects 403
    }

    @Test
    void unauthenticatedUserCannotDeleteOrder() throws Exception {
        // No @WithMockUser annotation means anonymous user
        mockMvc.perform(delete("/api/orders/123"))
            .andExpect(status().isUnauthorized());  // Expects 401
    }

    @Test
    @WithMockUser(username = "john", roles = "USER")
    void userCanAccessOwnOrder() throws Exception {
        mockMvc.perform(get("/api/orders/mine"))
            .andExpect(status().isOk());
    }
}
